export interface ExamInfo {
  id: number;
  key: string;
  name: string;
  short: string;
  emoji: string;
  questionBank?: { path: string; label: string }; // extra question bank page (table question_bank), when one exists
  program?: { path: string; label: string }; // learning/program page for this exam, when one exists
}

