export const getExamById = (id: number): ExamInfo | undefined => EXAM_CATALOG.find(e => e.id === id);
export const getExamByKey = (key: string): ExamInfo | undefined => EXAM_CATALOG.find(e => e.key === key);

// Accounts created before exams could be assigned (no exam_ids) keep the original behaviour: SAP-C02 only.
export const LEGACY_DEFAULT_EXAM_IDS = [2];

/** "1,2" | [1,2] | null  →  sorted unique ids (null when nothing is stored). */
export const parseExamIds = (raw: unknown): number[] | null => {
  if (raw === null || raw === undefined || raw === '') return null;
  const parts = Array.isArray(raw) ? raw : String(raw).split(',');
  const ids = parts.map(p => parseInt(String(p).trim(), 10)).filter(n => !isNaN(n));
  return ids.length ? Array.from(new Set(ids)).sort((a, b) => a - b) : null;
};

export const formatExamIds = (ids: number[]): string => Array.from(new Set(ids)).sort((a, b) => a - b).join(',');

const SESSION_KEY = 'userExams';

export const saveSessionExamIds = (ids: number[]) => sessionStorage.setItem(SESSION_KEY, JSON.stringify(ids));
export const clearSessionExamIds = () => { sessionStorage.removeItem(SESSION_KEY); sessionStorage.removeItem('userSetLimit'); };
const SET_LIMIT_KEY = 'userSetLimit';
/** user_access.no_of_sets: how many sets (from the lowest set number) the learner may open; null = no limit. */
export const saveSessionSetLimit = (n: number | null) => {
  if (n && n > 0) sessionStorage.setItem(SET_LIMIT_KEY, String(n)); else sessionStorage.removeItem(SET_LIMIT_KEY);
};
export const getSessionSetLimit = (): number | null => {
  const n = parseInt(sessionStorage.getItem(SET_LIMIT_KEY) || '', 10);
  return !isNaN(n) && n > 0 ? n : null;
};
/** The set numbers a learner may open: the first `limit` of the given set numbers (all when no limit). */
export const allowedSetNumbers = (setNumbers: number[], limit: number | null = getSessionSetLimit()): number[] => {
  const sorted = [...setNumbers].sort((a, b) => a - b);
  return limit ? sorted.slice(0, limit) : sorted;
};

export const getSessionExamIds = (): number[] => {
  try {
    const parsed = JSON.parse(sessionStorage.getItem(SESSION_KEY) || 'null');
    if (Array.isArray(parsed)) return parsed.filter((n: unknown) => typeof n === 'number') as number[];
  } catch { /* fall through */ }
  return LEGACY_DEFAULT_EXAM_IDS;
};
