import { supabase } from './supabase';
import { StaticPage } from '../types';

/**
 * Fetch all pages from page_master table
 */
export async function fetchAllPages(): Promise<{ success: boolean; data?: StaticPage[]; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('page_master')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Supabase fetch pages error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, data: data as StaticPage[] };
  } catch (error) {
    console.error('Fetch pages error:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Fetch a single page by slug
 */
export async function fetchPageBySlug(slug: string): Promise<{ success: boolean; data?: StaticPage; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('page_master')
      .select('*')
      .eq('slug', slug)
      .eq('is_published', true)
      .single();

    if (error) {
      console.error('Supabase fetch page by slug error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, data: data as StaticPage };
  } catch (error) {
    console.error('Fetch page by slug error:', error);
    return { success: false, error: String(error) };
  }
}

