/**
 * Fetch a single question by ID
 */
export async function fetchQuestionById(id: number): Promise<{ success: boolean; data?: QuestionMaster; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('question_master')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      console.error('Supabase fetch by ID error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, data };
  } catch (error) {
    console.error('Fetch question by ID error:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Convert exam type string to exam_id number
 * This maps the exam types from AddQuestionPage to database exam_ids
 */
export function getExamIdFromType(examType: string): number {
  const examTypeMap: Record<string, number> = {
    'saa': 1,
    'sap': 2,
    'ccp': 3,
    'dva': 4,
    'sysdesign': 5,
    'dsa': 6,
    'python': 7,
    'dotnet': 8,
    'aiml': 9,
  };
  return examTypeMap[examType] || 1;
}

/**
 * Convert category ID string to category_id number
 * Handles both numeric (1, 2, etc.) and custom (custom_1, etc.) formats
 */
export function getCategoryIdFromString(categoryId: string): number {
  // If it's already numeric, return as number
  const numericId = parseInt(categoryId);
  console.log('getCategoryIdFromString input:', categoryId, 'parsed:', numericId);
  if (!isNaN(numericId)) {
    return numericId;
  }
  
  // If it's a custom category like "saa_1", extract the number
  const parts = categoryId.split('_');
  if (parts.length > 1) {
    const lastPart = parts[parts.length - 1];
    const lastNumeric = parseInt(lastPart);
    if (!isNaN(lastNumeric)) {
      return lastNumeric + 1000; // Add offset to avoid conflict
    }
  }
  
  // Default fallback
  return 1;
}

/**
 * Format correct answer from array or number to comma-separated string
 */
export function formatCorrectAnswer(correctAnswer: number | number[]): string {
  if (Array.isArray(correctAnswer)) {
    return correctAnswer.map(a => String(a + 1)).join(',');
  }
  return String(correctAnswer + 1);
}

/**
 * Insert a new question into question_master table
 */
export async function insertQuestion(data: {
  examId: string;
  categoryId: string;
  question: string;
  options: string[];
  correctAnswer: number | number[];
  explaination: string;
  set?: number | null;
}): Promise<{ success: boolean; error?: string; data?: QuestionMaster }> {
  try {
    const examId = getExamIdFromType(data.examId);
    const categoryId = getCategoryIdFromString(data.categoryId);
    const correctAns = formatCorrectAnswer(data.correctAnswer);
    const options = data.options;
    
    const questionData: QuestionMaster = {
      exam_id: examId,
      category_id: categoryId,
      question: data.question,
      option1: options[0] || '',
      option2: options[1] || '',
      option3: options[2] || '',
      option4: options[3] || '',
      option5: options[4] || '',
      option6: options[5] || '',
      total_option: options.length,
      correct_ans: correctAns,
      explaination: data.explaination,
    };
    if (data.set !== undefined && data.set !== null) {
      questionData.set = data.set;
    }

    const { data: insertedData, error } = await supabase
      .from('question_master')
      .insert(questionData)
      .select()
      .single();

    if (error) {
      console.error('Supabase insert error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, data: insertedData };
  } catch (error) {
    console.error('Insert question error:', error);
    return { success: false, error: String(error) };
  }
}

