/**
 * Update an existing question
 */
export async function updateQuestion(
  id: number, 
  data: {
    examId?: string;
    categoryId?: string;
    question?: string;
    options?: string[];
    correctAnswer?: number | number[];
    explanation?: string;
    set?: number | null;
  }
): Promise<{ success: boolean; error?: string }> {
  try {
    const updateData: Partial<QuestionMaster> = {};
    
    if (data.examId !== undefined) {
      updateData.exam_id = getExamIdFromType(data.examId);
    }
    if (data.categoryId !== undefined) {
      updateData.category_id = getCategoryIdFromString(data.categoryId);
    }
    if (data.question !== undefined) {
      updateData.question = data.question;
    }
    if (data.options !== undefined) {
      updateData.option1 = data.options[0] || '';
      updateData.option2 = data.options[1] || '';
      updateData.option3 = data.options[2] || '';
      updateData.option4 = data.options[3] || '';
      updateData.option5 = data.options[4] || '';
      updateData.option6 = data.options[5] || '';
      updateData.total_option = data.options.length;
    }
    if (data.correctAnswer !== undefined) {
      updateData.correct_ans = formatCorrectAnswer(data.correctAnswer);
    }
    if (data.explanation !== undefined) {
      updateData.explaination = data.explanation;
    }
    if (data.set !== undefined) {
      updateData.set = data.set;
    }

    // Log for debugging
    console.log('Updating question ID:', id);
    console.log('Update data:', updateData);

    // Use select without single() to avoid issues
    const { data: _updatedData, error } = await supabase
      .from('question_master')
      .update(updateData)
      .eq('id', id)
      .select();

    console.log('Supabase response - data:', _updatedData, 'error:', error);

    if (error) {
      console.error('Supabase update error:', error);
      return { success: false, error: error.message };
    }

    // If no error but no data returned, check if update actually happened
    if (!_updatedData || _updatedData.length === 0) {
      console.error('No data returned from update - question may not exist');
      return { success: false, error: 'Question not found or update failed' };
    }

    console.log('Update succeeded, updated row:', _updatedData[0]);
    return { success: true };
  } catch (error) {
    console.error('Update question error:', error);
    return { success: false, error: String(error) };
  }
}

