/** Set (or clear, with null) the `set` of many questions at once. */
export async function updateQuestionsSet(ids: number[], set: number | null): Promise<{ success: boolean; error?: string }> {
  if (ids.length === 0) return { success: true };
  try {
    const { error } = await supabase.from('question_master').update({ set }).in('id', ids);
    if (error) {
      console.error('Supabase bulk set update error:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  } catch (error) {
    return { success: false, error: String(error) };
  }
}

