/**
 * Fetch questions and categories for an exam in a single API call
 * Returns both questions and grouped categories with counts
 */
export async function fetchExamData(examId: number): Promise<{
  success: boolean;
  questions?: QuestionMaster[];
  categories?: { category_id: number; label: string; count: number }[];
  error?: string;
}> {
  try {
    const { data, error } = await supabase
      .from('question_master')
      .select('id, exam_id, category_id, question, option1, option2, option3, option4, option5, option6, total_option, correct_ans, explaination, set')
      .eq('exam_id', examId)
      .order('id', { ascending: true });

    if (error) {
      console.error('Supabase fetch error:', error);
      return { success: false, error: error.message };
    }

    // A learner limited to N sets (user_access.no_of_sets) only gets the questions of those sets
    const limit = getSessionSetLimit();
    let rows = data || [];
    if (limit) {
      const allowed = new Set(allowedSetNumbers(Array.from(new Set(rows.map(r => r.set).filter((n): n is number => typeof n === 'number'))), limit));
      rows = rows.filter(r => typeof r.set === 'number' && allowed.has(r.set));
    }

    // Remove duplicates and group by category
    const uniqueQuestions = rows.reduce((acc: QuestionMaster[], q) => {
      if (!acc.find(existing => existing.id === q.id)) {
        acc.push(q);
      }
      return acc;
    }, []);

    // Build categories from the questions
    const categoryMap = new Map<number, number>();
    uniqueQuestions.forEach(q => {
      const catId = q.category_id;
      categoryMap.set(catId, (categoryMap.get(catId) || 0) + 1);
    });

    const categories = Array.from(categoryMap.entries()).map(([categoryId, count]) => ({
      category_id: categoryId,
      label: getCategoryLabel(examId, categoryId),
      count
    }));

    return { 
      success: true, 
      questions: uniqueQuestions,
      categories 
    };
  } catch (error) {
    console.error('Fetch exam data error:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Get category information for a specific exam from the database
 * Returns unique categories with question counts
 */
export async function fetchCategoriesByExam(examId: number): Promise<{
  success: boolean;
  data?: { category_id: number; label: string; count: number }[];
  error?: string;
}> {
  try {
    const { data, error } = await supabase
      .from('question_master')
      .select('category_id, question')
      .eq('exam_id', examId);

    if (error) {
      console.error('Supabase fetch categories error:', error);
      return { success: false, error: error.message };
    }

    // Group by category_id and count questions
    const categoryMap = new Map<number, number>();
    (data || []).forEach((q) => {
      const catId = q.category_id;
      categoryMap.set(catId, (categoryMap.get(catId) || 0) + 1);
    });

    // Create category info with labels based on exam type
    const categories = Array.from(categoryMap.entries()).map(([categoryId, count]) => {
      const label = getCategoryLabel(examId, categoryId);
      return { category_id: categoryId, label, count };
    });

    return { success: true, data: categories };
  } catch (error) {
    console.error('Fetch categories by exam error:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Bulk insert multiple questions into question_master table
 */
export async function bulkInsertQuestions(questions: QuestionMaster[]): Promise<{ success: boolean; error?: string; insertedCount?: number }> {
  try {
    if (questions.length === 0) {
      return { success: false, error: 'No questions to insert' };
    }

    let totalInserted = 0;
    const errors: string[] = [];
    const batchSize = 10;
    const questionDelay = 10000; // 10 seconds between each question
    const batchDelay = 300000; // 5 minutes between batches

    // Insert in batches of 10
    for (let i = 0; i < questions.length; i++) {
      // Add delay between each insert to avoid rate limiting
      if (i > 0) {
        // Check if we're starting a new batch
        if ((i) % batchSize === 0) {
          console.log(`Batch complete. Waiting ${batchDelay / 1000} seconds before next batch...`);
          await new Promise(resolve => setTimeout(resolve, batchDelay));
        } else {
          await new Promise(resolve => setTimeout(resolve, questionDelay));
        }
      }

      console.log(`Inserting question ${i + 1}/${questions.length}`);

      const { data, error } = await supabase
        .from('question_master')
        .insert(questions[i])
        .select();

      if (error) {
        console.error(`Insert error for question ${i + 1}:`, error);
        errors.push(`Q${i + 1}: ${error.message}`);
        continue;
      }

      totalInserted++;
    }

    console.log(`Total inserted: ${totalInserted}/${questions.length}`);
    if (errors.length > 0) {
      console.error('Insert errors:', errors);
    }

    if (totalInserted === 0 && questions.length > 0) {
      return { success: false, error: errors.join('; ') || 'Failed to insert questions' };
    }

    return { 
      success: totalInserted > 0, 
      insertedCount: totalInserted,
      error: errors.length > 0 ? `Imported ${totalInserted} questions. ${errors.length} failed.` : undefined
    };
  } catch (error) {
    console.error('Bulk insert questions error:', error);
    return { success: false, error: String(error) };
  }
}

