/* ───────────── Set-wise exam helpers (question_master.set) ───────────── */

export interface ExamSetSummary {
  set: number;
  count: number;
}

/** A question_master row converted to what the exam UI needs. `ans` holds 0-based indexes of every correct option. */
export interface SetExamQuestion {
  id: number;
  q: string;
  opts: string[];
  ans: number[];
  explain: string;
}

export function toSetExamQuestion(row: QuestionMaster): SetExamQuestion {
  const all = [row.option1, row.option2, row.option3, row.option4, row.option5, row.option6];
  const total = row.total_option > 0 ? Math.min(row.total_option, 6) : 4;
  const opts = all.slice(0, total).map(o => o ?? '');
  const ans = String(row.correct_ans ?? '')
    .split(',')
    .map(x => parseInt(x.trim(), 10) - 1)
    .filter(n => !isNaN(n) && n >= 0 && n < opts.length);
  return { id: row.id ?? 0, q: row.question, opts, ans, explain: row.explaination || '' };
}

/** Distinct sets of an exam with the number of questions in each, ordered by set number. */
export async function fetchExamSets(examId: number): Promise<{ success: boolean; sets?: ExamSetSummary[]; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('question_master')
      .select('set')
      .eq('exam_id', examId)
      .not('set', 'is', null);

    if (error) {
      console.error('Supabase fetch sets error:', error);
      return { success: false, error: error.message };
    }

    const counts = new Map<number, number>();
    (data || []).forEach((r: { set: number | null }) => {
      if (r.set !== null && r.set !== undefined) counts.set(r.set, (counts.get(r.set) || 0) + 1);
    });
    const sets = Array.from(counts.entries())
      .map(([set, count]) => ({ set, count }))
      .sort((a, b) => a.set - b.set);
    return { success: true, sets };
  } catch (error) {
    console.error('Fetch sets error:', error);
    return { success: false, error: String(error) };
  }
}

/** All questions of one set, in a stable order (by id). */
export async function fetchQuestionsBySet(examId: number, setNo: number): Promise<{ success: boolean; questions?: SetExamQuestion[]; error?: string; locked?: boolean }> {
  try {
    // A learner limited to N sets (user_access.no_of_sets) cannot load the questions of the other sets
    if (getSessionSetLimit()) {
      const all = await fetchExamSets(examId);
      if (!all.success || !all.sets) return { success: false, error: all.error || 'Could not check set access.' };
      if (!allowedSetNumbers(all.sets.map(s => s.set)).includes(setNo)) {
        return { success: false, locked: true, error: 'This set is not included in your plan.' };
      }
    }
    const { data, error } = await supabase
      .from('question_master')
      .select('id, exam_id, category_id, question, option1, option2, option3, option4, option5, option6, total_option, correct_ans, explaination, set')
      .eq('exam_id', examId)
      .eq('set', setNo)
      .order('id', { ascending: true });

    if (error) {
      console.error('Supabase fetch by set error:', error);
      return { success: false, error: error.message };
    }

    return { success: true, questions: (data || []).map(r => toSetExamQuestion(r as QuestionMaster)) };
  } catch (error) {
    console.error('Fetch questions by set error:', error);
    return { success: false, error: String(error) };
  }
}
